-- ============================================================
-- DEMO WORK PROGRAMS KABINET CERITA LOKA 2026
--
-- File terpisah dari 000_ministries.sql
-- 17 kementerian, 108 program kerja
-- Jumlah program tiap kementerian dibuat bervariasi antara 3 sampai 10
-- Idempotent berdasarkan UNIQUE KEY (ministry_id, slug)
-- Target: MySQL 8
-- ============================================================

SET NAMES utf8mb4 COLLATE utf8mb4_unicode_ci;

START TRANSACTION;

DROP TEMPORARY TABLE IF EXISTS seed_demo_work_programs;

CREATE TEMPORARY TABLE seed_demo_work_programs (
    unit_code          VARCHAR(50)  NOT NULL,
    name               VARCHAR(180) NOT NULL,
    slug               VARCHAR(200) NOT NULL,
    short_description  VARCHAR(500) NULL,
    description        LONGTEXT     NULL,
    objectives         TEXT         NULL,
    target_audience    TEXT         NULL,
    start_date         DATE         NULL,
    end_date           DATE         NULL,
    execution_month    VARCHAR(50)  NULL,
    lifecycle_status   VARCHAR(20)  NOT NULL,
    display_order      INT UNSIGNED NOT NULL,
    is_featured        BOOLEAN      NOT NULL DEFAULT FALSE,
    meta_title         VARCHAR(180) NULL,
    meta_description   VARCHAR(255) NULL,
    PRIMARY KEY (unit_code, slug)
)
ENGINE = InnoDB
DEFAULT CHARACTER SET utf8mb4
COLLATE utf8mb4_unicode_ci;

