INSERT INTO work_programs (
    ministry_id,
    name,
    slug,
    short_description,
    description,
    objectives,
    target_audience,
    start_date,
    end_date,
    execution_month,
    lifecycle_status,
    cover_media_id,
    display_order,
    is_featured,
    is_published,
    published_at,
    created_by,
    updated_by,
    meta_title,
    meta_description,
    created_at,
    updated_at
)
SELECT
    ministry.id,
    seed.name,
    seed.slug,
    seed.short_description,
    seed.description,
    seed.objectives,
    seed.target_audience,
    seed.start_date,
    seed.end_date,
    seed.execution_month,
    seed.lifecycle_status,
    NULL,
    seed.display_order,
    seed.is_featured,
    TRUE,
    NOW(),
    NULL,
    NULL,
    seed.meta_title,
    seed.meta_description,
    NOW(),
    NOW()
FROM seed_demo_work_programs AS seed
INNER JOIN ministries AS ministry
    ON ministry.code COLLATE utf8mb4_unicode_ci
     = seed.unit_code COLLATE utf8mb4_unicode_ci
WHERE
    ministry.unit_type = 'KEMENTERIAN'
    AND ministry.is_active = TRUE
ON DUPLICATE KEY UPDATE
    name = VALUES(name),
    short_description = VALUES(short_description),
    description = VALUES(description),
    objectives = VALUES(objectives),
    target_audience = VALUES(target_audience),
    start_date = VALUES(start_date),
    end_date = VALUES(end_date),
    execution_month = VALUES(execution_month),
    lifecycle_status = VALUES(lifecycle_status),
    display_order = VALUES(display_order),
    is_featured = VALUES(is_featured),
    is_published = VALUES(is_published),
    published_at = COALESCE(work_programs.published_at, VALUES(published_at)),
    meta_title = VALUES(meta_title),
    meta_description = VALUES(meta_description),
    updated_at = NOW();

DROP TEMPORARY TABLE IF EXISTS seed_demo_work_programs;

COMMIT;

SELECT
    ministry.code AS ministry_code,
    ministry.name AS ministry_name,
    COUNT(program.id) AS total_work_programs
FROM ministries AS ministry
LEFT JOIN work_programs AS program
    ON program.ministry_id = ministry.id
WHERE
    ministry.unit_type = 'KEMENTERIAN'
    AND ministry.cabinet_term_id = (
        SELECT id
        FROM cabinet_terms
        WHERE slug = 'cerita-loka-2026'
        LIMIT 1
    )
GROUP BY
    ministry.id,
    ministry.code,
    ministry.name,
    ministry.display_order
ORDER BY
    ministry.parent_id ASC,
    ministry.display_order ASC;